  impact: ["Each subclass has zero or more attributes and can therefore be generically represented as a HList of these attributes. 6 The term ‘coproduct’ represents a generalized notion of ‘sum’ inherited from Category Theory. implicit val productBase = new Size[HNil] { def size(x: HNil): Int = 0 } implicit def productInductionStep[H, T <: HList]( implicit h: Size[H], t: Size[T]) = new Size[H :: T] { def size(x: H :: T) = { val hd = h.size(x.head) val tl = t.size(x.tail) hd + tl } } implicit val coproductBase = new Size[CNil] { def size(x: CNil): Int = 0 } implicit def coproductInductionStep[H, T <: Coproduct]( implicit h: Size[H], t: Size[T]) = new Size[H :+: T] { def size(x: H :+: T): Int = x match { case Inl(l) => h.size(l) case Inr(r) => t.size(r) } } Listing 6."],
